package external

import (
	"reflect"

	"git.duti.dev/secure-package-registry/pkg/apidef"
	"git.duti.dev/secure-package-registry/pkg/pkgdb"
	"git.duti.dev/secure-package-registry/pkg/verification"
)

// Routes returns the route definitions for all external API endpoints.
// These are consumed by cmd/apigen to generate the OpenAPI paths section.
func Routes() []apidef.RouteDef {
	return []apidef.RouteDef{
		// --- Public package routes ---
		{
			Method:       "GET",
			Path:         "/api/v1/svc/packages",
			Summary:      "Search packages",
			Description:  "Search for packages by query string. Returns all packages (paginated) if no query is provided.",
			Tag:          "Packages",
			OperationID:  "searchPackages",
			ResponseType: reflect.TypeOf(pkgdb.SearchResult{}),
			SuccessCode:  200,
			QueryParams: []apidef.QueryParam{
				{Name: "q", Description: "Search query string"},
				{Name: "ecosystem", Description: "Filter by ecosystem (npm, go, cargo, pypi)"},
				{Name: "page", Description: "Page number (default 1)"},
				{Name: "page_size", Description: "Page size (default 20, max 100)"},
			},
		},
		{
			Method:       "GET",
			Path:         "/api/v1/svc/packages/{ecosystem}/{identifier}/{version}",
			Summary:      "Get package version",
			Description:  "Retrieve details for a specific package version.",
			Tag:          "Packages",
			OperationID:  "getPackageVersion",
			ResponseType: reflect.TypeOf(pkgdb.PackageVersion{}),
			SuccessCode:  200,
			PathParams:   []string{"ecosystem", "identifier", "version"},
		},
		{
			Method:       "POST",
			Path:         "/api/v1/svc/packages/{ecosystem}/{identifier}/{version}/verify",
			Summary:      "Verify package version",
			Description:  "Re-check upstream attestation and OSS rebuild status for a package version.",
			Tag:          "Packages",
			OperationID:  "verifyPackageVersion",
			ResponseType: reflect.TypeOf(verification.Result{}),
			SuccessCode:  200,
			PathParams:   []string{"ecosystem", "identifier", "version"},
		},
		{
			Method:       "GET",
			Path:         "/api/v1/svc/packages/{ecosystem}/{identifier}/versions",
			Summary:      "List package versions",
			Description:  "List all known versions for a package with their verification status.",
			Tag:          "Packages",
			OperationID:  "listPackageVersionsPublic",
			ResponseType: reflect.TypeOf(pkgdb.VersionListResult{}),
			SuccessCode:  200,
			PathParams:   []string{"ecosystem", "identifier"},
		},

		// --- Admin routes ---
		{
			Method:       "GET",
			Path:         "/api/v1/admin/packages",
			Summary:      "List watched packages",
			Description:  "List all watched packages for a given ecosystem.",
			Tag:          "Admin",
			OperationID:  "adminListPackages",
			ResponseType: reflect.TypeOf(PackageListResponse{}),
			SuccessCode:  200,
			QueryParams: []apidef.QueryParam{
				{Name: "ecosystem", Description: "Ecosystem to list packages for", Required: true},
			},
		},
		{
			Method:       "POST",
			Path:         "/api/v1/admin/packages",
			Summary:      "Add package to watch list",
			Description:  "Create a new package in the watch list and publish a package requested event.",
			Tag:          "Admin",
			OperationID:  "adminAddPackage",
			RequestBody:  reflect.TypeOf(AddPackageRequest{}),
			ResponseType: reflect.TypeOf(AddPackageResponse{}),
			SuccessCode:  201,
		},
		{
			Method:       "GET",
			Path:         "/api/v1/admin/packages/{ecosystem}/{identifier}/versions",
			Summary:      "List package versions",
			Description:  "List all known versions for a package.",
			Tag:          "Admin",
			OperationID:  "adminListVersions",
			ResponseType: reflect.TypeOf(ListVersionsResponse{}),
			SuccessCode:  200,
			PathParams:   []string{"ecosystem", "identifier"},
		},
		{
			Method:       "POST",
			Path:         "/api/v1/admin/packages/{ecosystem}/{identifier}/scan",
			Summary:      "Trigger behavioral analysis scan",
			Description:  "Trigger a behavioral analysis scan for a package version. Defaults to the latest version if none is specified.",
			Tag:          "Admin",
			OperationID:  "adminTriggerScan",
			RequestBody:  reflect.TypeOf(TriggerScanRequest{}),
			ResponseType: reflect.TypeOf(TriggerScanResponse{}),
			SuccessCode:  201,
			PathParams:   []string{"ecosystem", "identifier"},
		},
		{
			Method:         "GET",
			Path:           "/api/v1/admin/packages/{ecosystem}/{identifier}/behavior",
			Summary:        "Get behavioral analysis (deduped)",
			Description:    "Return the pre-computed deduped behavioral analysis tree for a specific package version.",
			Tag:            "Admin",
			OperationID:    "adminGetBehavior",
			SuccessCode:    200,
			PathParams:     []string{"ecosystem", "identifier"},
			StreamResponse: true,
			ContentType:    "application/json",
			QueryParams: []apidef.QueryParam{
				{Name: "version", Description: "Package version to retrieve behavior for", Required: true},
			},
		},
		{
			Method:         "GET",
			Path:           "/api/v1/admin/packages/{ecosystem}/{identifier}/behavior/raw",
			Summary:        "Get behavioral analysis (raw)",
			Description:    "Return the raw (non-deduped) behavioral analysis tree for a specific package version.",
			Tag:            "Admin",
			OperationID:    "adminGetBehaviorRaw",
			SuccessCode:    200,
			PathParams:     []string{"ecosystem", "identifier"},
			StreamResponse: true,
			ContentType:    "application/json",
			QueryParams: []apidef.QueryParam{
				{Name: "version", Description: "Package version to retrieve behavior for", Required: true},
			},
		},
		{
			Method:       "GET",
			Path:         "/api/v1/admin/tasks",
			Summary:      "List collection tasks",
			Description:  "List collection tasks with package context, optionally filtered by ecosystem.",
			Tag:          "Admin",
			OperationID:  "adminListTasks",
			ResponseType: reflect.TypeOf(TaskListResponse{}),
			SuccessCode:  200,
			QueryParams: []apidef.QueryParam{
				{Name: "ecosystem", Description: "Filter by ecosystem"},
				{Name: "page", Description: "Page number (default 1)"},
				{Name: "page_size", Description: "Page size (default 50, max 100)"},
			},
		},
		{
			Method:         "GET",
			Path:           "/api/v1/admin/tasks/{taskID}/artifact",
			Summary:        "Download task artifact",
			Description:    "Stream the behavioral analysis artifact (.jsonl) for a completed collection task.",
			Tag:            "Admin",
			OperationID:    "adminDownloadArtifact",
			SuccessCode:    200,
			PathParams:     []string{"taskID"},
			StreamResponse: true,
			ContentType:    "application/x-ndjson",
		},

		// --- Project routes (authenticated) ---
		{
			Method:       "POST",
			Path:         "/api/v1/projects",
			Summary:      "Upload project",
			Description:  "Create or replace a project's dependency set from a lockfile or package manifest.",
			Tag:          "Projects",
			OperationID:  "uploadProject",
			RequestBody:  reflect.TypeOf(UploadProjectRequest{}),
			ResponseType: reflect.TypeOf(UploadProjectResponse{}),
			SuccessCode:  201,
			Auth:         true,
		},
		{
			Method:       "GET",
			Path:         "/api/v1/projects",
			Summary:      "List projects",
			Description:  "List all projects belonging to the authenticated user.",
			Tag:          "Projects",
			OperationID:  "listProjects",
			ResponseType: reflect.TypeOf(ProjectListResponse{}),
			SuccessCode:  200,
			Auth:         true,
		},
		{
			Method:       "GET",
			Path:         "/api/v1/projects/{projectID}",
			Summary:      "Get project",
			Description:  "Get a single project by ID.",
			Tag:          "Projects",
			OperationID:  "getProject",
			ResponseType: reflect.TypeOf(GetProjectResponse{}),
			SuccessCode:  200,
			PathParams:   []string{"projectID"},
			Auth:         true,
		},
		{
			Method:       "GET",
			Path:         "/api/v1/projects/{projectID}/dependencies",
			Summary:      "List project dependencies",
			Description:  "List dependencies for a project, optionally filtered by type.",
			Tag:          "Projects",
			OperationID:  "listDependencies",
			ResponseType: reflect.TypeOf(DependencyListResponse{}),
			SuccessCode:  200,
			PathParams:   []string{"projectID"},
			Auth:         true,
			QueryParams: []apidef.QueryParam{
				{Name: "type", Description: "Filter by dependency type: 'direct' or 'transitive'"},
			},
		},
		{
			Method:       "GET",
			Path:         "/api/v1/projects/{projectID}/summary",
			Summary:      "Get project summary",
			Description:  "Get aggregated security posture statistics for a project.",
			Tag:          "Projects",
			OperationID:  "getProjectSummary",
			ResponseType: reflect.TypeOf(ProjectSummaryResponse{}),
			SuccessCode:  200,
			PathParams:   []string{"projectID"},
			Auth:         true,
		},
		{
			Method:      "DELETE",
			Path:        "/api/v1/projects/{projectID}",
			Summary:     "Delete project",
			Description: "Delete a project and all its dependencies.",
			Tag:         "Projects",
			OperationID: "deleteProject",
			SuccessCode: 204,
			PathParams:  []string{"projectID"},
			Auth:        true,
		},
	}
}
